PAGE = """<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width">
<title>AI Voice Studio</title><style>
:root{color-scheme:dark;font:15px system-ui;background:#0d1017;color:#edf1f7}body{max-width:1050px;margin:32px auto;padding:0 20px}header{display:flex;align-items:end;justify-content:space-between}h1{margin:0;font-size:30px}small,.muted{color:#9da9ba}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:16px;margin-top:22px}section{background:#171d29;border:1px solid #293247;border-radius:12px;padding:20px}input,select,button{box-sizing:border-box;margin:5px 0;padding:9px;border-radius:7px;border:1px solid #3b465d;background:#10151f;color:#edf1f7}input{width:100%}button{background:#6dd5ae;color:#07120e;border:0;font-weight:700;cursor:pointer}pre{white-space:pre-wrap;word-break:break-word;background:#0e131c;padding:12px;border-radius:8px;min-height:42px}.badge{display:inline-block;padding:3px 7px;border-radius:20px;background:#293247;margin:3px}audio{width:100%;margin-top:10px}</style></head>
<body><header><div><h1>AI Voice Studio <small>V0.1</small></h1><div class="muted">本地音声工作流 · 能力状态如实标记</div></div><button onclick="refresh()">刷新状态</button></header>
<main class="grid">
<section><h2>项目</h2><input id="projectName" placeholder="项目名称"><button onclick="createProject()">创建项目</button><pre id="projects">加载中…</pre></section>
<section><h2>音频处理</h2><select id="audioProject"><option value="">不关联项目</option></select><input id="audioFile" type="file" accept="audio/*"><button onclick="runAudio()">校验并标准化 WAV</button><pre id="audioResult">等待任务</pre><audio id="player" controls hidden></audio></section>
<section><h2>AI 念话</h2><select id="ttsProject"><option value="">不关联项目</option></select><textarea id="ttsText" placeholder="输入生成文本" style="width:100%;min-height:80px"></textarea><input id="ttsReference" type="file" accept="audio/*"><input id="ttsPrompt" placeholder="参考音频对应文本（可选）"><button onclick="runTts()">提交 GPT-SoVITS 任务</button><pre id="ttsResult">需要配置外部 GPT-SoVITS API</pre><audio id="ttsPlayer" controls hidden></audio></section>
<section><h2>RVC 音色转换</h2><select id="rvcProject"><option value="">不关联项目</option></select><input id="rvcInput" type="file" accept="audio/*"><input id="rvcModel" placeholder="已登记的 RVC .pth 模型 ID"><input id="rvcIndex" placeholder="已登记的 .index 模型 ID（可选）"><input id="rvcPitch" type="number" value="0" placeholder="移调半音"><button onclick="runRvc()">提交 Applio RVC 任务</button><pre id="rvcResult">需要配置外部 Applio 环境</pre><audio id="rvcPlayer" controls hidden></audio></section>
<section><h2>AI 翻唱预设</h2><select id="coverProject"><option value="">不关联项目</option></select><input id="coverSong" type="file" accept="audio/*"><input id="coverModel" placeholder="已登记的 RVC .pth 模型 ID"><input id="coverIndex" placeholder="已登记的 .index 模型 ID（可选）"><input id="coverPitch" type="number" value="0" placeholder="移调半音"><input id="coverChunk" type="number" value="0" min="0" step="1" placeholder="分块秒数；0 表示关闭"><input id="coverOverlap" type="number" value="1" min="0.01" step="0.1" placeholder="重叠秒数"><button onclick="runCover()">运行翻唱预设工作流</button><pre id="coverResult">分离 → RVC → 客观质量比较 → 混合；可选重叠分块用于边界优化</pre><audio id="coverPlayer" controls hidden></audio></section>
<section><h2>人声/伴奏分离</h2><input id="separationInput" type="file" accept="audio/*"><select id="separationModel"><option value="htdemucs">htdemucs</option><option value="htdemucs_ft">htdemucs_ft</option></select><button onclick="runSeparation()">提交 Demucs 任务</button><pre id="separationResult">需要配置外部 Demucs 环境；模型权重不随项目分发</pre></section>
<section><h2>人声与伴奏混合</h2><input id="mixVocals" type="file" accept="audio/*"><input id="mixAccompaniment" type="file" accept="audio/*"><input id="mixVocalGain" type="number" value="0" step="0.5" placeholder="人声增益 dB"><input id="mixAccompanimentGain" type="number" value="0" step="0.5" placeholder="伴奏增益 dB"><button onclick="runMix()">对齐并混合</button><pre id="mixResult">等待任务</pre><audio id="mixPlayer" controls hidden></audio></section>
<section><h2>原创演唱</h2><input id="midiFile" type="file" accept=".mid,.midi"><button onclick="inspectMidi()">解析 MIDI</button><textarea id="singingLyrics" placeholder="歌词；中文按单字、拉音用 -，英文按空格分词" style="width:100%;min-height:70px"></textarea><button onclick="alignSinging()">对齐歌词与 MIDI</button><pre id="midiResult">可验证 BPM、音符、时长、休止和歌词音节对齐；尚未音素化</pre><input id="singingDs" type="file" accept=".ds"><input id="singingExperiment" placeholder="DiffSinger 实验/模型名称"><input id="singingSpeaker" placeholder="说话人名称（可选）"><input id="singingKey" type="number" value="0" placeholder="移调半音"><button onclick="runSinging()">提交 DiffSinger 任务</button><pre id="singingResult">需要配置外部 DiffSinger 环境和合法唱声模型</pre><audio id="singingPlayer" controls hidden></audio></section>
<section><h2>音频质量筛查</h2><input id="qualityFile" type="file" accept="audio/*"><button onclick="analyzeQuality()">分析客观指标</button><pre id="qualityResult">检查峰值、削波、静音占比、内部静音段和采样突变；不能替代试听</pre></section>
<section><h2>处理前后比较</h2><input id="compareBefore" type="file" accept="audio/*"><input id="compareAfter" type="file" accept="audio/*"><button onclick="compareQuality()">比较客观指标</button><pre id="compareResult">差值只描述信号变化，不自动判断听感优劣</pre></section>
<section><h2>RVC 训练</h2><input id="datasetName" placeholder="数据集名称"><input id="datasetLicense" placeholder="数据授权/许可证（必填）"><input id="datasetFiles" type="file" accept="audio/*" multiple><button onclick="importDataset()">登记训练音频</button><pre id="datasets">尚未登记数据集</pre><input id="trainingDataset" placeholder="数据集 ID"><input id="trainingModel" placeholder="模型名称（英文/数字/下划线/连字符）"><input id="trainingEpochs" type="number" value="200" min="1"><input id="trainingBatch" type="number" value="4" min="1"><button onclick="runTraining()">提交 RVC 训练任务</button><pre id="trainingResult">需要配置外部 Applio 环境；当前真实训练未验证</pre></section>
<section><h2>模型登记</h2><select id="modelType"><option value="rvc">RVC</option><option value="gpt-sovits">GPT-SoVITS</option><option value="singing">唱声模型</option></select><input id="modelLicense" placeholder="模型许可证/授权说明（必填）"><input id="modelSource" placeholder="来源 URL"><input id="modelFile" type="file"><button onclick="registerModel()">登记模型文件</button><pre id="models">加载中…</pre></section>
<section><h2>任务控制</h2><input id="jobControlId" placeholder="任务 ID"><button onclick="retryJob()">重新执行任务</button><button onclick="cancelJob()">取消任务</button><pre id="jobControlResult">当前全部工作流任务均支持按原始参数重新执行；缺失输入、模型或引擎时会明确提示</pre></section>
<section><h2>能力状态</h2><div id="capabilities">加载中…</div><h2>最近任务</h2><pre id="jobs">加载中…</pre></section>
</main><script>
const show=(id,value)=>document.getElementById(id).textContent=typeof value==='string'?value:JSON.stringify(value,null,2);
async function json(url,options){const r=await fetch(url,options);const data=await r.json();if(!r.ok)throw new Error(data.detail||r.statusText);return data}
function fillProjects(select,projects){const selected=select.value;select.replaceChildren(new Option('不关联项目',''),...projects.map(project=>new Option(project.name,project.id)));select.value=projects.some(project=>project.id===selected)?selected:''}
async function refresh(){try{const [p,m,d,j,c]=await Promise.all([json('/api/projects'),json('/api/models'),json('/api/datasets'),json('/api/jobs'),json('/api/capabilities')]);show('projects',p);show('models',m);show('datasets',d);show('jobs',j);fillProjects(audioProject,p);fillProjects(ttsProject,p);fillProjects(rvcProject,p);fillProjects(coverProject,p);const box=document.getElementById('capabilities');box.replaceChildren(...Object.entries(c).map(([k,v])=>{const e=document.createElement('div');e.className='badge';e.textContent=`${k}: ${v}`;return e}))}catch(e){show('jobs',e.message)}}
async function createProject(){try{await json('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:projectName.value})});projectName.value='';refresh()}catch(e){show('projects',e.message)}}
async function runAudio(){if(!audioFile.files[0])return show('audioResult','请选择音频文件');const d=new FormData();d.append('file',audioFile.files[0]);d.append('project_id',audioProject.value);try{const job=await json('/api/workflow/audio',{method:'POST',body:d});show('audioResult',job);poll(job.id)}catch(e){show('audioResult',e.message)}}
async function poll(id){const timer=setInterval(async()=>{try{const job=await json('/api/jobs/'+id);show('audioResult',job);if(['completed','failed','cancelled'].includes(job.status)){clearInterval(timer);if(job.output){player.src=job.output;player.hidden=false}refresh()}}catch(e){clearInterval(timer);show('audioResult',e.message)}},400)}
async function runTts(){if(!ttsReference.files[0])return show('ttsResult','请选择授权参考音频');const d=new FormData();d.append('text',ttsText.value);d.append('text_lang','zh');d.append('prompt_lang','zh');d.append('prompt_text',ttsPrompt.value);d.append('project_id',ttsProject.value);d.append('reference_audio',ttsReference.files[0]);try{const job=await json('/api/workflow/tts',{method:'POST',body:d});show('ttsResult',job);pollTts(job.id)}catch(e){show('ttsResult',e.message)}}
async function pollTts(id){const timer=setInterval(async()=>{try{const job=await json('/api/jobs/'+id);show('ttsResult',job);if(['completed','failed','cancelled'].includes(job.status)){clearInterval(timer);if(job.output){ttsPlayer.src=job.output;ttsPlayer.hidden=false}refresh()}}catch(e){clearInterval(timer);show('ttsResult',e.message)}},400)}
async function runRvc(){if(!rvcInput.files[0])return show('rvcResult','请选择输入音频');const d=new FormData();d.append('input_audio',rvcInput.files[0]);d.append('model_id',rvcModel.value);d.append('index_model_id',rvcIndex.value);d.append('pitch',rvcPitch.value);d.append('project_id',rvcProject.value);try{const job=await json('/api/workflow/voice-conversion',{method:'POST',body:d});show('rvcResult',job);pollRvc(job.id)}catch(e){show('rvcResult',e.message)}}
async function pollRvc(id){const timer=setInterval(async()=>{try{const job=await json('/api/jobs/'+id);show('rvcResult',job);if(['completed','failed','cancelled'].includes(job.status)){clearInterval(timer);if(job.output){rvcPlayer.src=job.output;rvcPlayer.hidden=false}refresh()}}catch(e){clearInterval(timer);show('rvcResult',e.message)}},400)}
async function runCover(){if(!coverSong.files[0])return show('coverResult','请选择歌曲音频');const d=new FormData();d.append('song',coverSong.files[0]);d.append('model_id',coverModel.value);d.append('index_model_id',coverIndex.value);d.append('pitch',coverPitch.value);d.append('chunk_seconds',coverChunk.value);d.append('overlap_seconds',coverOverlap.value);d.append('project_id',coverProject.value);try{const job=await json('/api/workflow/cover',{method:'POST',body:d});show('coverResult',job);pollSimple(job.id,'coverResult',coverPlayer)}catch(e){show('coverResult',e.message)}}
async function runSeparation(){if(!separationInput.files[0])return show('separationResult','请选择歌曲音频');const d=new FormData();d.append('input_audio',separationInput.files[0]);d.append('model',separationModel.value);try{const job=await json('/api/workflow/separate',{method:'POST',body:d});show('separationResult',job);pollSimple(job.id,'separationResult')}catch(e){show('separationResult',e.message)}}
async function runMix(){if(!mixVocals.files[0]||!mixAccompaniment.files[0])return show('mixResult','请选择人声和伴奏');const d=new FormData();d.append('vocals',mixVocals.files[0]);d.append('accompaniment',mixAccompaniment.files[0]);d.append('vocal_gain_db',mixVocalGain.value);d.append('accompaniment_gain_db',mixAccompanimentGain.value);try{const job=await json('/api/workflow/mix',{method:'POST',body:d});show('mixResult',job);pollSimple(job.id,'mixResult',mixPlayer)}catch(e){show('mixResult',e.message)}}
async function pollSimple(id,resultId,audioElement){const timer=setInterval(async()=>{try{const job=await json('/api/jobs/'+id);show(resultId,job);if(['completed','failed','cancelled'].includes(job.status)){clearInterval(timer);if(audioElement&&job.output){audioElement.src=job.output;audioElement.hidden=false}refresh()}}catch(e){clearInterval(timer);show(resultId,e.message)}},400)}
async function inspectMidi(){if(!midiFile.files[0])return show('midiResult','请选择 MIDI 文件');const d=new FormData();d.append('file',midiFile.files[0]);try{show('midiResult',await json('/api/midi/inspect',{method:'POST',body:d}))}catch(e){show('midiResult',e.message)}}
async function alignSinging(){if(!midiFile.files[0])return show('midiResult','请选择 MIDI 文件');const d=new FormData();d.append('midi_file',midiFile.files[0]);d.append('lyrics',singingLyrics.value);try{show('midiResult',await json('/api/singing/align',{method:'POST',body:d}))}catch(e){show('midiResult',e.message)}}
async function runSinging(){if(!singingDs.files[0])return show('singingResult','请选择 DiffSinger DS 文件');const d=new FormData();d.append('ds_file',singingDs.files[0]);d.append('experiment',singingExperiment.value);d.append('speaker',singingSpeaker.value);d.append('key',singingKey.value);try{const job=await json('/api/workflow/singing',{method:'POST',body:d});show('singingResult',job);pollSimple(job.id,'singingResult',singingPlayer)}catch(e){show('singingResult',e.message)}}
async function analyzeQuality(){if(!qualityFile.files[0])return show('qualityResult','请选择音频文件');const d=new FormData();d.append('file',qualityFile.files[0]);try{show('qualityResult',await json('/api/audio/analyze',{method:'POST',body:d}))}catch(e){show('qualityResult',e.message)}}
async function compareQuality(){if(!compareBefore.files[0]||!compareAfter.files[0])return show('compareResult','请选择处理前后两个音频');const d=new FormData();d.append('before',compareBefore.files[0]);d.append('after',compareAfter.files[0]);try{show('compareResult',await json('/api/audio/compare',{method:'POST',body:d}))}catch(e){show('compareResult',e.message)}}
async function importDataset(){if(!datasetFiles.files.length)return show('datasets','请选择授权训练音频');const d=new FormData();d.append('name',datasetName.value);d.append('license_name',datasetLicense.value);for(const file of datasetFiles.files)d.append('files',file);try{const result=await json('/api/datasets',{method:'POST',body:d});trainingDataset.value=result.id;show('datasets',result);refresh()}catch(e){show('datasets',e.message)}}
async function runTraining(){const d=new FormData();d.append('dataset_id',trainingDataset.value);d.append('model_name',trainingModel.value);d.append('total_epoch',trainingEpochs.value);d.append('batch_size',trainingBatch.value);try{const job=await json('/api/workflow/train-rvc',{method:'POST',body:d});show('trainingResult',job);pollSimple(job.id,'trainingResult')}catch(e){show('trainingResult',e.message)}}
async function registerModel(){const d=new FormData();d.append('model_type',modelType.value);d.append('license_name',modelLicense.value);d.append('source_url',modelSource.value);if(!modelFile.files[0])return show('models','请选择模型文件');d.append('file',modelFile.files[0]);try{const m=await json('/api/models',{method:'POST',body:d});show('models',m);refresh()}catch(e){show('models',e.message)}}
async function retryJob(){if(!jobControlId.value.trim())return show('jobControlResult','请输入任务 ID');try{const job=await json('/api/jobs/'+encodeURIComponent(jobControlId.value.trim())+'/retry',{method:'POST'});show('jobControlResult',job);jobControlId.value=job.id;refresh()}catch(e){show('jobControlResult',e.message)}}
async function cancelJob(){if(!jobControlId.value.trim())return show('jobControlResult','请输入任务 ID');try{show('jobControlResult',await json('/api/jobs/'+encodeURIComponent(jobControlId.value.trim())+'/cancel',{method:'POST'}));refresh()}catch(e){show('jobControlResult',e.message)}}
refresh();
</script></body></html>"""
